```python
class Solution:
    def punishmentNumber(self, n: int) -> int:
        total = 0
        for i in range(1, n + 1):
            sq = i * i
            if self.canPartition(sq, i):
                total += i * i
        return total

    def canPartition(self, s: str, target: int) -> bool:
        # Check if string s can be partitioned to sum to target
        # This is a standard backtracking problem
        return self.dfs(s, 0, 0, target)

    def dfs(self, s: str, start: int, current_sum: int, target: int) -> bool:
        if current_sum == target:
            return start == len(s)
        if current_sum > target:
            return False

        for end in range(start + 1, len(s) + 1):
            num = int(s[start:end])
            if self.dfs(s, end, current_sum + num, target):
                return True
        return False
